local a=peripheral.find("inventory")if not peripheral.hasType(a,"inventory")then return end;local b=a;b.itemTypes={}b.freeSpace=0;print("[storage] indexing ...")local c=b.list()for d=1,#c do local e,f=pcall(b.getItemDetail,d)if f==nil or not e then b.freeSpace=b.freeSpace+64 elseif e and not b.itemTypes[f.name]then table.insert(b.itemTypes,{f.name,f.displayName,f.maxCount})end;if d%10==1 then print("[storage] indexing: "..d/#c*100 .."%")end end;b.freeSpace=b.freeSpace+(b.size()-#c)*64;print("[storage] indexing complete.")print("[storage] free space: "..b.freeSpace)function b.count()local g=0;for d,h in pairs(b.list())do if h~=nil and h.count~=nil then g=g+h.count end end;return g end;function b.maxCount()local g=(b.size()-#b.list())*64;for d,h in pairs(b.list())do if h~=nil then maxToAdd=64;if b.itemTypes[h.name]then maxToAdd=b.itemTypes[h.name]end;g=g+maxToAdd end end;return g end;function b.percentage()return math.floor(b.count()/b.maxCount()*100)end;return b
